# -*- coding: utf-8 -*-
"""把已从游戏资源里提取的日文串，批量送本机翻译服务，结果写入
AutoTranslator/Translation/zh/Text/_AutoGeneratedTranslations.txt（静态译文，游戏里 0 延迟）。
"""
import argparse, html, json, os, re, shutil, sys, time, urllib.parse, urllib.request

GAME = r"C:\Users\yourname\Desktop\game！\ss\示例游戏"
OUT = os.path.join(GAME, "AutoTranslator", "Translation", "zh", "Text",
                   "_AutoGeneratedTranslations.txt")
HERE = os.path.dirname(os.path.abspath(__file__))
SRV = "http://127.0.0.1:8791/translate"

JP_CH = re.compile(r"[\u3040-\u30ff\u4e00-\u9fff\u3005\u3006\u30fc\uff01-\uff60\u3001\u3002]")
KANA = re.compile(r"[\u3040-\u30ff]")
BAD = set("¢°†‡§¶¥¤¦¨¬®¯±²³µ·¸¹º»¼½¾¿×÷ヽヾㇰㇱㇲㇳㇴㇵㇶㇷㇸㇹㇺㇻㇼㇽㇾㇿゕゖ")


def looks_real(s):
    if not (2 <= len(s) <= 180):
        return False
    if not KANA.search(s):
        return False
    if any(ch in BAD for ch in s):
        return False
    jp = len(JP_CH.findall(s))
    if jp / len(s) < 0.55:
        return False
    # 夹杂的 ASCII 不能太长
    if re.search(r"[A-Za-z]{6,}", s):
        return False
    # 真正的假名（排除长音符 ー 与中点），用来排除「あいうえお」这类字母表/符号表
    real_kana = len(re.findall(r"[\u3041-\u3096\u30a1-\u30fa]", s))
    if real_kana < 1:
        return False
    kanji = len(re.findall(r"[\u4e00-\u9fff]", s))
    has_punct = bool(re.search(r"[、。！？!?「」『』…]|\s", s))
    if kanji == 0 and not has_punct and len(s) > 8:
        return False
    return True


def esc(v):
    return v.replace("\\", "\\\\").replace("\n", "\\n").replace("\r", "")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--limit", type=int, default=0)
    ap.add_argument("--srv", default=SRV)
    a = ap.parse_args()

    src = []
    for f in ("jp_strings.json", "jp_big.json"):
        p = os.path.join(HERE, f)
        if os.path.exists(p):
            src += json.load(open(p, encoding="utf-8"))
    uniq = []
    seen = set()
    for s in src:
        s = s.strip()
        if s in seen:
            continue
        seen.add(s)
        if looks_real(s):
            uniq.append(s)

    existing = {}
    if os.path.exists(OUT):
        for raw in open(OUT, encoding="utf-8-sig").read().splitlines():
            if "=" in raw:
                k, v = raw.split("=", 1)
                existing[k] = v

    todo = [s for s in uniq if s not in existing]
    if a.limit:
        todo = todo[:a.limit]
    print(f"candidates={len(uniq)} existing={len(existing)} todo={len(todo)}")
    if a.dry_run:
        for s in todo[:60]:
            print("  ", s)
        return

    gl = {}
    gp = os.path.join(HERE, "glossary.json")
    if os.path.exists(gp):
        gl = json.load(open(gp, encoding="utf-8"))

    done = 0
    t0 = time.time()
    for s in todo:
        if s in gl:
            continue
        try:
            q = urllib.parse.urlencode({"from": "ja", "to": "zh", "text": s})
            r = urllib.request.urlopen(f"{a.srv}?{q}", timeout=180)
            out = r.read().decode("utf-8")
        except Exception as e:
            print("ERR", repr(s)[:40], e)
            continue
        if not out or out.strip() == s or not re.search(r"[\u4e00-\u9fff]", out):
            continue
        existing[s] = out
        done += 1
        if done % 10 == 0:
            print(f"  {done}/{len(todo)}  {time.time()-t0:.0f}s", flush=True)

    # 写回文件（保留原有条目顺序，追加新条目）
    lines = [f"{k}={esc(v)}" for k, v in existing.items() if v]
    shutil.copy2(OUT, OUT + ".prefill_bak") if os.path.exists(OUT) else None
    with open(OUT, "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")
    print(f"translated {done} new, total {len(lines)} -> {OUT}  ({time.time()-t0:.0f}s)")


if __name__ == "__main__":
    main()
